const inputData = $('Execute Workflow Trigger').first()?.json || {};
const paisObjetivo = (inputData.pais_origen || 'China').trim().toLowerCase();

const inventarios = $('Obtener Inventario').all().map(i => i.json);
const declaraciones = $('Obtener Declaraciones').all().map(i => i.json);
const productos = $('Obtener Productos').all().map(i => i.json);
const paises = $('Obtener Paises').all().map(i => i.json);
const bodegas = $('Obtener Bodegas').all().map(i => i.json);

const paisMap = new Map(paises.map(p => [p.id_pais, p.nombre]));
const decMap = new Map(declaraciones.map(d => [d.id_declaracion, d]));
const prodMap = new Map(productos.map(p => [p.id_producto, p]));
const bodegaMap = new Map(bodegas.map(b => [b.id_bodega, b.nombre]));

const resultados = [];
for (const inv of inventarios) {
  if (Number(inv.cantidad_almacenada) <= 0 || inv.fecha_salida) continue;
  const dec = decMap.get(inv.id_declaracion);
  if (!dec || dec.estado !== 'Retenida') continue;
  const prod = prodMap.get(inv.id_producto);
  if (!prod) continue;
  const paisNombre = paisMap.get(prod.id_pais_origen) || '';
  if (paisNombre.toLowerCase() !== paisObjetivo) continue;

  resultados.push({
    numero_dua: dec.numero_dua,
    estado_declaracion: dec.estado,
    producto: prod.nombre_comercial,
    sku: prod.codigo_sku,
    pais_origen_mercancia: paisNombre,
    cantidad_almacenada: Number(inv.cantidad_almacenada),
    unidad_medida: inv.unidad_medida,
    nombre_bodega: bodegaMap.get(inv.id_bodega) || 'Sin Bodega',
    ubicacion_estante: inv.ubicacion_estante
  });
}

resultados.sort((a, b) => a.numero_dua.localeCompare(b.numero_dua) || a.producto.localeCompare(b.producto));

return [{
  json: {
    estado: 'exitoso',
    herramienta: 'consultar_mercancia_retenida_por_origen',
    filtros: { pais_origen: inputData.pais_origen || 'China', estado_declaracion: 'Retenida', stock_activo: true },
    total_registros: resultados.length,
    es_parcial: false,
    datos: resultados
  }
}];
